{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Linezolid, a close oxazolidinone analogue (Morgan similarity 0.4507), has approximately 100% absolute oral bioavailability in humans, directly supporting high oral bioavailability for the query's oxazolidinone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Delpazolid (LCB01-0371), another oxazolidinone with an aryl substituent on the oxazolidinone nitrogen, showed 99.75% absolute oral bioavailability in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Contezolid, a related oxazolidinone, had an absolute bioavailability of 0.64 in healthy subjects, still well above the 20% threshold and supportive of high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808, a linezolid-like oxazolidinone with a thiomorpholine ring, had low absolute bioavailability of 10.1% (range 2.3–19.3%), providing contradictory evidence; however, its thiomorpholine and acetyl features differ from the query's morpholinone and chlorothiophene amide, reducing transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Cadazolid, a gut-restricted oxazolidinone, had very low oral bioavailability, but it is intentionally designed to be non-absorbed and is structurally less similar to the query, so it carries limited weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oxazolidinone with favorable physicochemical properties. The closest high-quality human data come from linezolid and delpazolid, both showing near-complete oral bioavailability, and contezolid also exceeds 20%. The only close analogue with low F is YH4808, but its specific thiomorpholine/acetyl features differ from the query's morpholinone and chlorothiophene amide, and the broader oxazolidinone class tends to be well absorbed. Overall, evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data are available for the query molecule.",
    "The effect of the fed state on absorption and bioavailability is not directly addressed by the evidence.",
    "The mechanism underlying YH4808's low bioavailability is not established, limiting assessment of whether that liability transfers.",
    "Metabolic stability and first-pass clearance of the chlorothiophene amide moiety are unknown.",
    "Solubility under fed conditions is not experimentally measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

